%[output:56f71dd2]
%   data: {"dataType":"text","outputData":{"text":"  固定(N=120):       22.4 dB\n","truncated":false}}
%---
%[output:25a449d2]
%   data: {"dataType":"text","outputData":{"text":"  自适应(N=64,μ=0.05): 22.4 dB  ||θ||=0.3\n","truncated":false}}
